lns="http://www.w3.org/2000/svg" x="0" y="0" text-anchor="middle" transform="translate(226.9252232142857 315.84)" fill="#000000" font-size="19.84" font-family="Crimson Text">3</text><line xmlns="http://www.w3.org/2000/svg" x1="273.1640625" x2="273.1640625" y1="96" y2="296" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text xmlns="http://www.w3.org/2000/svg" x="0" y="0" text-anchor="middle" transform="translate(273.1640625 315.84)" fill="#000000" font-size="19.84" font-family="Crimson Text">4</text><line xmlns="http://www.w3.org/2000/svg" x1="319.4029017857143" x2="319.4029017857143" y1="96" y2="296" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text xmlns="http://www.w3.org/2000/svg" x="0" y="0" text-anchor="middle" transform="translate(319.4029017857143 315.84)" fill="#000000" font-size="19.84" font-family="Crimson Text">5</text><line xmlns="http://www.w3.org/2000/svg" x1="365.64174107142856" x2="365.64174107142856" y1="96" y2="296" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text xmlns="http://www.w3.org/2000/svg" x="0" y="0" text-anchor="middle" transform="translate(365.64174107142856 315.84)" fill="#000000" font-size="19.84" font-family="Crimson Text">6</text><line xmlns="http://www.w3.org/2000/svg" x1="411.88058035714283" x2="411.88058035714283" y1="96" y2="296" fill="none" stroke="#000000" stroke-linecap="round" stroke-linejoin="round" stroke-width="0.9"/><text xmlns="http://www.w3.org/2000/svg" x="0" y="0" text-anchor="middle" transform="translate(411.88058035714283 315.84)" fill="#000000" font-size="19.84" font-family="Crimson Text">7</text><text text-anchor="middle" transform="translate(273.1640625 24)" fill="#000000" font-size="19.84" font-family="Crimson Text">Participants’ Likability Ratings for</text><text text-anchor="middle" transform="translate(273.1640625 48)" fill="#000000" font-size="19.84" font-family="Crimson Text">Candidates by Candidates’ Traits</text><text text-anchor="middle" transform="translate(273.1640625 72)" fill="#000000" font-size="19.84" font-family="Crimson Text">and Participants’ Ignoble-Trait Scores</text><text text-anchor="middle" transform="translate(273.1640625 349.67999999999995)" fill="#000000" font-size="19.84" font-family="Crimson Text">Ignoble-trait scores of participants</text><rect xmlns="http://www.w3.org/2000/svg" fill="none" x="90.0234375" y="366.84000000000003" height="71" width="284.953125" stroke="#000000" stroke-linejoin="mitre" stroke-width="0.9"/><line x1="97.0234375" y1="383.84000000000003" x2="124.0234375" y2="383.84000000000003" stroke="#000" stroke-width="2.4" marker-end="url(#marker0)"/><line x1="124.0234375" y1="383.84000000000003" x2="151.0234375" y2="383.84000000000003" stroke="#000" stroke-width="2.4" marker-start="url(#marker0)"/><text transform="translate(161.0234375 390.84000000000003)" text-anchor="top" fill="#000000" font-size="19.84" font-family="Crimson Text"> admirable-trait candidates</text><line x1="97.0234375" y1="415.84000000000003" x2="124.0234375" y2="415.84000000000003" stroke="#000" stroke-width="2.4" stroke-dasharray="9 6" marker-end="url(#marker1)"/><line x1="124.0234375" y1="415.84000000000003" x2="151.0234375" y2="415.84000000000003" stroke="#000" stroke-width="2.4" stroke-dasharray="9 6" marker-start="url(#marker1)"/><text transform="translate(161.0234375 422.84000000000003)" text-anchor="top" fill="#000000" font-size="19.84" font-family="Crimson Text"> ignoble-trait candidates</text><line x1="134.44754464285714" y1="162" x2="180.68638392857142" y2="162" stroke="#000" stroke-width="2.4" marker-end="url(#marker0)" marker-start="url(#marker0)"/><line x1="134.44754464285714" y1="254" x2="180.68638392857142" y2="234" stroke="#000" stroke-width="2.4" stroke-dasharray="9 6" marker-end="url(#marker1)" marker-start="url(#marker1)"/><line x1="180.68638392857142" y1="162" x2="226.9252232142857" y2="162" stroke="#000" stroke-width="2.4" marker-end="url(#marker0)" marker-start="url(#marker0)"/><line x1="180.68638392857142" y1="234" x2="226.9252232142857" y2="214" stroke="#000" stroke-width="2.4" stroke-dasharray="9 6" marker-end="url(#marker1)" marker-start="url(#marker1)"/><line x1="226.9252232142857" y1="162" x2="273.1640625" y2="162" stroke="#000" stroke-width="2.4" marker-end="url(#marker0)" marker-start="url(#marker0)"/><line x1="226.9252232142857" y1="214" x2="273.1640625" y2="198" stroke="#000" stroke-width="2.4" stroke-dasharray="9 6" marker-end="url(#marker1)" marker-start="url(#marker1)"/><line x1="273.1640625" y1="162" x2="319.4029017857143" y2="162" stroke="#000" stroke-width="2.4" marker-end="url(#marker0)" marker-start="url(#marker0)"/><line x1="273.1640625" y1="198" x2="319.4029017857143" y2="176" stroke="#000" stroke-width="2.4" stroke-dasharray="9 6" marker-end="url(#marker1)" marker-start="url(#marker1)"/><line x1="319.4029017857143" y1="162" x2="365.64174107142856" y2="159" stroke="#000" stroke-width="2.4" marker-end="url(#marker0)" marker-start="url(#marker0)"/><line x1="319.4029017857143" y1="176" x2="365.64174107142856" y2="158" stroke="#000" stroke-width="2.4" stroke-dasharray="9 6" marker-end="url(#marker1)" marker-start="url(#marker1)"/><line x1="365.64174107142856" y1="159" x2="411.88058035714283" y2="159" stroke="#000" stroke-width="2.4" marker-end="url(#marker0)" marker-start="url(#marker0)"/><line x1="365.64174107142856" y1="158" x2="411.88058035714283" y2="133" stroke="#000" stroke-width="2.4" stroke-dasharray="9 6" marker-end="url(#marker1)" marker-start="url(#marker1)"/></g></svg></figure><div class="sr-only" role="region" aria-label="Long description for line graph titled Participants’ Likeability Ratings for Candidates by Candidates’ Traits and Participants’ Ignoble-Trait Scores"><ul>
<li>All values are approximate.</li>
<li>The following 2 lines are shown:<br/>
<ul>
<li>admirable-trait candidates</li>
<li>ignoble-trait candidates</li>
</ul>
</li>
<li>The admirable-trait candidates line:<br/>
<ul>
<li>Begins at 1, 67</li>
<li>Remains level to 2, 67&nbsp;</li>
<li>Remains level to 3, 67</li>
<li>Remains level to 4, 67</li>
<li>Remains level to 5, 67</li>
<li>Rises gradually to 6, 69</li>
<li>Remains level to 7, 69</li>
</ul>
</li>
<li>The ignoble-trait candidates line:&nbsp;<br/>
<ul>
<li>Begins at 1, 21</li>
<li>Rises gradually to 2, 31</li>
<li>Rises gradually to 3, 41</li>
<li>Rises gradually to 4, 49</li>
<li>Rises gradually to 5, 60</li>
<li>Rises gradually to 6, 69</li>
<li>Rises gradually to 7, 82</li>
</ul>
</li>
</ul></div>
<p>Alessandro Nai <span data-ssml-sub-alias="et al">et al.</span> presented study participants with vignettes about fictive political candidates, portraying them as embodying a personality trait widely considered admirable (<span data-ssml-sub-alias="e g">e.g.</span>, agreeableness) or one considered ignoble (<span data-ssml-sub-alias="e g">e.g.</span>, cynicism). A survey recorded participants&rsquo; ratings of the candidates&rsquo; likability and showed that across participants, ignoble-trait candidates were less likable than admirable-trait candidates. However, when the researchers factored in the participants&rsquo; own personality-trait scores, on a scale of 1 (least ignoble) to 7 (most ignoble), they concluded that this relative ranking of candidates persisted except among the participants with high ignobility scores.</p>$SATQ$, $SATQ$<p>Which choice best describes data from the graph that support the researchers&rsquo; conclusion?</p>$SATQ$, $SATQ$[{"id":"949bd5a0-0af6-46c2-8a07-c47cba6339d7","content":"<p>There was a strong positive correlation between participants&rsquo; ignobility scores and admirable-trait candidates&rsquo; likability ratings, but there was no correlation between ignobility scores and ignoble-trait candidates&rsquo; likability ratings.</p>"},{"id":"569ad6e7-4d41-4c80-a3e4-d56c678bd272","content":"<p>Participants with an ignobility score of 5 or less rated admirable-trait candidates as more likable than ignoble-trait candidates, whereas participants with an ignobility score of 6 or more rated ignoble-trait candidates as equally likable as or even more likable than admirable-trait candidates.</p>"},{"id":"544b8443-3396-47db-b607-e515889717c9","content":"<p>Overall, participants rated admirable-trait candidates as quite likable, and that rating was not significantly affected by the participants&rsquo; ignobility scores.</p>"},{"id":"1afe4a93-a431-4888-9829-df13b140accf","content":"<p>Unlike participants with an ignobility score of 6, participants with an ignobility score either greater or less than 6 gave admirable-trait candidates and ignoble-trait candidates different likability ratings.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["569ad6e7-4d41-4c80-a3e4-d56c678bd272"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it describes data from the graph that support the researchers&rsquo; conclusion that the trend of admirable-trait candidates being rated as more likable than ignoble-trait candidates held true when participants&rsquo; own personality-trait scores were factored in, except among participants with high ignobility scores. The values on the x-axis represent survey participants grouped by their own ignobility scores, from low ignobility (1) to high ignobility (7), while the values on the y-axis represent the likability scores given to the political candidates. The graph shows that the full range of participants (from least to most ignoble) gave the admirable-trait candidates (represented by the line with triangles) a likability rating of approximately 70 out of 100; that is, regardless of their own level of ignobility, participants generally found admirable-trait candidates quite likable. However, the graph shows that participants varied in their views of ignoble-trait candidates (represented by the line with squares); likability ratings increased as the participants&rsquo; own ignobility scores increased. Participants with low to medium-high ignobility scores (1 to 5) still rated the ignoble-trait candidates as less likable than the admirable-trait candidates, with all ratings falling below approximately 70, but participants with high ignobility scores (6 and 7) gave ratings equal to or higher than approximately 70. In other words, the previously observed trend of ranking admirable-trait candidates as more likable than ignoble-trait candidates persisted for participants with low to medium-high ignobility but not for participants with high ignobility.</p><p>Choice A is incorrect because it describes the opposite of what the graph shows. The graph shows a positive correlation between participants&rsquo; ignobility scores and ignoble-trait candidates&rsquo; likability ratings (as participants&rsquo; ignobility scores increased, so did their ratings for ignoble-trait candidates&rsquo; likability) and no correlation between ignobility scores and admirable-trait candidates&rsquo; likability ratings (all participants gave admirable-trait candidates a rating of approximately 70 out of 100). Choice C is incorrect. The graph does show that regardless of their own ignobility scores, participants rated admirable-trait candidates as quite likable (a rating of approximately 70 out of 100). However, this doesn&rsquo;t support the researchers&rsquo; conclusion because the conclusion has to do with how participants rated both types of candidates, not just the admirable-trait ones; moreover, the conclusion is that relative ratings were actually affected by the participants&rsquo; ignobility scores. Choice D is incorrect. The graph does show that only participants with an ignobility score of 6 gave the same likability score to both admirable- and ignoble-trait candidates while participants with other ignobility scores gave a different rating for each candidate, but this doesn&rsquo;t support the researchers&rsquo; conclusion. The conclusion isn&rsquo;t just that participants gave different ratings to the two types of candidates&mdash;it&rsquo;s that participants with low to medium-high ignobility scores specifically gave higher likability ratings to admirable-trait candidates than to ignoble-trait candidates and that participants with high ignobility scores didn&rsquo;t.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"82bdf676","external_id":"0c85a491-b942-44d2-9407-d63cefec2ad9","vaultid":null,"uId":"a0da658e-28a1-4dc5-a64f-6ebfeba02c3e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"INI","domain":"Information and Ideas","skill_cd":"COE","skill_desc":"Command of Evidence","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<figure class=\"image\"><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"450\" height=\"448.84\" viewBox=\"0 0 450 448.84\" role=\"img\" aria-label=\"Line graph titled Participants’ Likeability Ratings for Candidates by Candidates’ Traits and Participants’ Ignoble-Trait Scores. The horizontal axis is labeled Ignoble-trait scores of participants. It ranges from 1 to 7 in increments of 1. The vertical axis is labeled Candidate-likeability score (higher score = more likeable). It ranges from 0 to 100 in increments of 25. 2 lines are shown. Refer to long description.\"><g id=\"ed420550-79eb-48d4-af01-cd27cdd08afd\" data-name=\"Layer 1\"><defs>\n      <marker id=\"marker0\" markerWidth=\"6\" markerHeight=\"6\" refX=\"3\" refY=\"3\" markerUnits=\"strokeWidth\">\n        <polygon points=\"3 0, 0 5.196, 6 5.196\" fill=\"#000\"/>\n      </marker>\n      <marker id=\"marker1\" markerWidth=\"5\" markerHeight=\"5\" refX=\"2.5\" refY=\"2.5\" markerUnits=\"strokeWidth\">\n        <path d=\"M0,0 L0,5 L5,5 L5,0 z\" fill=\"#BBB\" stroke=\"#000\" stroke-width=\"1.5\"/>\n      </marker>\n      <marker id=\"marker2\" markerWidth=\"6\" markerHeight=\"6\" refX=\"3\" refY=\"3\" markerUnits=\"strokeWidth\">\n        <circle cx=\"3\" cy=\"3\" r=\"1.8\" fill=\"#FFF\" stroke=\"#000\" stroke-width=\".6\"/>\n      </marker>\n      <marker id=\"marker3\" markerWidth=\"6\" markerHeight=\"6\" refX=\"3\" refY=\"3\" markerUnits=\"strokeWidth\">\n        <polygon points=\"0.5 3, 2.3 2.3, 3 0.5, 3.7 2.3, 5.5 3, 3.7 3.7, 3 5.5, 2.3 3.7, 0.5 3\" fill=\"#999\" stroke-linejoin=\"round\" stroke=\"#000\" stroke-width=\".5\"/>\n      </marker>\n    </defs><line xmlns=\"http://www.w3.org/2000/svg\" x1=\"111.328125\" y1=\"96\" x2=\"435\" y2=\"96\" fill=\"none\" stroke=\"#000000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-wi